-- ----------------------------
-- Table structure for app_news
-- ----------------------------
DROP TABLE IF EXISTS `app_news`;
CREATE TABLE `app_news` (
  `news_id` int NOT NULL AUTO_INCREMENT COMMENT '新闻ID',
  `category_id` int NOT NULL DEFAULT '1' COMMENT '新闻栏目ID',
  `author` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '作者',
  `title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '标题',
  `img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '新闻图片',
  `desc` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '新闻简介',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '新闻内容',
  `sort` tinyint(1) NOT NULL DEFAULT '0' COMMENT '排序，数字越大权重越高',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用，2停用，3删除',
  `news_time` int NOT NULL DEFAULT '0' COMMENT '新闻时间',
  `created_at` int NOT NULL DEFAULT '0' COMMENT '创建时间',
  `updated_at` int NOT NULL DEFAULT '0' COMMENT '更新时间',
  PRIMARY KEY (`news_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='新闻表';

-- ----------------------------
-- Records of app_news
-- ----------------------------
BEGIN;
INSERT INTO `app_news` (`news_id`, `category_id`, `author`, `title`, `img`, `desc`, `content`, `sort`, `status`, `news_time`, `created_at`, `updated_at`) VALUES (1, 1, 'admin', '中芯国际消息正式发布，三个方面值得关注', '/upload/newsImg/20220708/1657249598_2022323143536821.jpg', '', '<p data-from-paste=\"1\" style=\"border: none; font-family: arial; font-size: 16px; overflow-y: auto; max-width: 100%; line-height: 24px; margin-bottom: 0px !important;\">因为台积电停止芯片代工，华为没有了高端芯片支持，手机业务出现了严重下滑。可见，芯片对于企业发展有多么重要。然而，高端芯片制造我们至今还是不能解决。</p><p style=\"border: none; color: rgb(51, 51, 51); font-family: arial; font-size: 16px; overflow-y: auto; max-width: 100%; line-height: 24px; margin-bottom: 0px !important;\">不过，幸好我们还有中芯国际、华虹半导体等本土晶圆代工企业，尽管还做不了高端芯片，但需求最大的成熟制程芯片不至于受限制。如今，中芯国际又传来了消息。<br></p><p style=\"border: none; color: rgb(51, 51, 51); font-family: arial; font-size: 16px; overflow-y: auto; max-width: 100%; line-height: 24px; margin-bottom: 0px !important;\">业绩再创新高，增速又领先试想下，如果没有中芯国际这样能够进入到全球前五的晶圆企业，我们会有更多的企业在芯片上受限制。就比如俄地区，近两个月来芯片方面被断供，影响就非常大。在全球缺芯的关键时刻，中芯国际也发挥了不小的作用。为解决缺芯问题，中芯一直在扩大产能，把现在产能拉到了极致，因此抓住了发展的良机，实现了业绩提升。2021年，中芯国际净利润突破了百亿大关，在年增长率上超过了台积电、三星等。近日，中芯国际正式发布了今年第一季度财报，业绩再创历史新高。营收实现了同比增长66.9%，毛利同比增长200%，净利润同比增长391%，继续在快速增长中。值得一提的是，台积电今年第一季度营收同比增长为36%，再次被中芯国际超过。当然，我们只是比较的营收的增速，营收数额还差得多，因为光市场份额台积电就是中芯的10倍之多。不过，增速能够超过也很了不起，说明中芯进展的速度非常快。</p><p style=\"border: none; color: rgb(51, 51, 51); font-family: arial; font-size: 16px; overflow-y: auto; max-width: 100%; line-height: 24px; margin-bottom: 0px !important;\">台积电、三星在全球晶圆代工市场的份额最多，两家加起来能够占到70%左右，他们都涨价了，基本上整个行业价格也就起来了，但中芯国际却没有传出涨价的消息。并且近日财报会上，中芯国际还表示重点考虑长远的战略合作，而不是短期赚更多的钱，因此没有宣布全面涨价，只是对有些客户进行了涨价，并且也没有涨那么多。要知道，如今中芯国际依然还在美“实体清单”中，现在能够取得这样的成绩实属不易。由此可见，中芯国际找到了最适合形势的发展道路，抓住了当前的发展良机。</p><div class=\"index-module_textWrap_3ygOc  \" style=\"margin-top: 22px; border: none; color: rgb(51, 51, 51); font-family: arial; font-size: 16px; background-color: rgb(255, 255, 255); max-width: 100%; overflow-x: visible; line-height: 24px;\"><div class=\"index-module_textWrap_3ygOc  \" style=\"margin-top: 24px; border: none; max-width: 100%; overflow-x: visible; line-height: 24px;\"><p style=\"border: none; overflow-y: auto; max-width: 100%; line-height: 24px; margin-bottom: 0px !important;\">希望中芯国际能够继续稳步前进，继续增强实力，为后续更好发展储备更多力量！</p></div></div>', 0, 1, 1656574902, 1656574927, 1657249599);
INSERT INTO `app_news` (`news_id`, `category_id`, `author`, `title`, `img`, `desc`, `content`, `sort`, `status`, `news_time`, `created_at`, `updated_at`) VALUES (2, 1, 'admin', '使用美光存储芯片的好处有哪些', '/upload/newsImg/20220708/1657249585_2022323143527841.jpg', '', '<p style=\"margin-bottom: 0px; border: none; color: rgb(102, 102, 102); list-style: none; font-family: &quot;microsoft yahei&quot;, simsun, arial; background-color: rgb(255, 255, 255);\">现在如今电子设备和智能终端等这一半导体元器件的使用日渐增强，高品质的美光存储芯片本身在云计算和大数据处理等环节资中发挥了重要的价值，而如今高品质的美光存储芯片会提质系统存储和数据计算带来了更好的效果，利用这种高品质的美光存储芯片为信息化发展和相应的计算机行业发展夯实了基础。</p><p style=\"margin-bottom: 0px; border: none; color: rgb(102, 102, 102); list-style: none; font-family: &quot;microsoft yahei&quot;, simsun, arial; background-color: rgb(255, 255, 255);\"><br></p><p style=\"margin-bottom: 0px; border: none; color: rgb(102, 102, 102); list-style: none; font-family: &quot;microsoft yahei&quot;, simsun, arial; background-color: rgb(255, 255, 255);\">1.能够更好的提升计算系统的竞争力</p><p style=\"margin-bottom: 0px; border: none; color: rgb(102, 102, 102); list-style: none; font-family: &quot;microsoft yahei&quot;, simsun, arial; background-color: rgb(255, 255, 255);\">在对比美光存储芯片哪家好的一系列的特点时可以发现目前性能更好的美光存储芯片低能耗设计提升了其技术的稳定性，与此同时其芯片的构架也提高了高速缓存的能力，让这种高稳定性的美光存储芯片线的芯片漏电流得到了有效的降低，因此美光存储芯片本身的使用时间和可用性得到了不断的提升，应用这种高品质的美光存储芯片也能够更好的改进，现如今设备的技术效果和各种物联终端的性能。</p><p style=\"margin-bottom: 0px; border: none; color: rgb(102, 102, 102); list-style: none; font-family: &quot;microsoft yahei&quot;, simsun, arial; background-color: rgb(255, 255, 255);\">2.能够有效的改善数据存储的稳定度</p><p style=\"margin-bottom: 0px; border: none; color: rgb(102, 102, 102); list-style: none; font-family: &quot;microsoft yahei&quot;, simsun, arial; background-color: rgb(255, 255, 255);\">据悉目前品质更好的美光存储芯片本身的功耗更加稳定，在使用时也能够达到更高的筛选次数，因此高品质的美光存储芯片本身的数据保持能力和抗辐射磁场效果等得到了更好的改进。而这种高品质的美光存储芯片在数据缓存和表象存储之中达到了更好的介质效果，因此使用可靠的美光存储芯片在更大程度上提升了其半导体的装置的存储价值。</p><p style=\"margin-bottom: 0px; border: none; color: rgb(102, 102, 102); list-style: none; font-family: &quot;microsoft yahei&quot;, simsun, arial; background-color: rgb(255, 255, 255);\">总而言之高品质的美光存储芯片本身的数据存储工艺和稳定性更好，而美光存储芯片的服务水平和其技术体系也随之提升，让后续的软件技术和其数据存储的质量更好，为其存储部分的设计带来了更好的效果，降低了整体芯片的功耗并且改善了技术稳定度。</p><p><br></p>', 0, 1, 1656574937, 1656574963, 1659080223);
INSERT INTO `app_news` (`news_id`, `category_id`, `author`, `title`, `img`, `desc`, `content`, `sort`, `status`, `news_time`, `created_at`, `updated_at`) VALUES (3, 1, 'admin', 'XILINX品牌芯片与altera芯片的不同主要表现在哪些方面', '/upload/newsImg/20220708/1657249574_2022323143517622.jpg', '', '<p style=\"margin-bottom: 0px; border: none; color: rgb(102, 102, 102); list-style: none; font-family: &quot;microsoft yahei&quot;, simsun, arial; background-color: rgb(255, 255, 255);\">据大量的市场销售数据表明近些年XILINX品牌芯片的销售量逐年递增，它以控制性能稳定、功耗小以及结构简单而闻名于世。有关XILINX品牌芯片哪家服务好的咨询声更是络绎不绝，现在就XILINX品牌芯片与altera芯片的不同主要表现在哪些方面作简要阐述：</p><p style=\"margin-bottom: 0px; border: none; color: rgb(102, 102, 102); list-style: none; font-family: &quot;microsoft yahei&quot;, simsun, arial; background-color: rgb(255, 255, 255);\"><br></p><p style=\"margin-bottom: 0px; border: none; color: rgb(102, 102, 102); list-style: none; font-family: &quot;microsoft yahei&quot;, simsun, arial; background-color: rgb(255, 255, 255);\">1.市场的高低端定位不同</p><p style=\"margin-bottom: 0px; border: none; color: rgb(102, 102, 102); list-style: none; font-family: &quot;microsoft yahei&quot;, simsun, arial; background-color: rgb(255, 255, 255);\">XILINX品牌芯片可以帮助许多产品实现多项不同功能的控制，而它与altera芯片的不同主要在于高低端定位上。一般来说XILINX品牌芯片的定位更偏向于某些高性能的控制类产品，比如机器人或者智能设备等；而altera芯片的市场定位更偏向于某些中低档的产品。</p><p style=\"margin-bottom: 0px; border: none; color: rgb(102, 102, 102); list-style: none; font-family: &quot;microsoft yahei&quot;, simsun, arial; background-color: rgb(255, 255, 255);\">2.系统开发规模的大小</p><p style=\"margin-bottom: 0px; border: none; color: rgb(102, 102, 102); list-style: none; font-family: &quot;microsoft yahei&quot;, simsun, arial; background-color: rgb(255, 255, 255);\">据大量的对比数据分析显示XILINX品牌芯片与altera芯片的不同还主要表现在系统开发规模的大小上。一般来说XILINX品牌芯片在软件开发上的能力非常强，因此它更适宜应用于大规模系统的开发作业；而altera芯片的精细化与自动化控制能力较弱，故而更适宜小规格系统的开发与应用。</p><p style=\"margin-bottom: 0px; border: none; color: rgb(102, 102, 102); list-style: none; font-family: &quot;microsoft yahei&quot;, simsun, arial; background-color: rgb(255, 255, 255);\">3.逻辑单元不同</p><p style=\"margin-bottom: 0px; border: none; color: rgb(102, 102, 102); list-style: none; font-family: &quot;microsoft yahei&quot;, simsun, arial; background-color: rgb(255, 255, 255);\">XILINX品牌芯片的逻辑单元分布与altera芯片也存在较大不同。Xilinx的逻辑单元为逻辑阵列模块LAB，而Altera的逻辑单元为可配置逻辑块CLB，因此这两者在应用上有明显的不同。</p><p style=\"margin-bottom: 0px; border: none; color: rgb(102, 102, 102); list-style: none; font-family: &quot;microsoft yahei&quot;, simsun, arial; background-color: rgb(255, 255, 255);\">XILINX品牌芯片是FPGA应用领域较为知名的芯片产品，这也促使越来越多的芯片开发商不断在线刷新XILINX品牌芯片售后服务怎样。它与altera芯片的不同除了表现在市场的高低端定位不同外，还表现在系统开发规模的大小不同以及逻辑单元不同上。</p><p><br></p>', 0, 1, 1656574974, 1656574994, 1659080215);
INSERT INTO `app_news` (`news_id`, `category_id`, `author`, `title`, `img`, `desc`, `content`, `sort`, `status`, `news_time`, `created_at`, `updated_at`) VALUES (4, 2, '转载：文章来源易容网   (www.mlcc1.com)', '必看！黄奇帆回应，疫情下全球产业链重构与中国应对', '/upload/newsImg/20220708/1657249554_202232314410198.jpg', '', '<section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">疫情之下，全球产业链会发生怎样的重构？产业链会撤出中国吗？如何维护和确保中国产业链的完整通畅？围绕这些问题，中国国际经济交流中心副理事长黄奇帆在5月27日晚上的浦山讲坛上发表了题为“全球产业链重构与中国应对”的演讲。</section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">黄奇帆认为，在全球产业链的结构性重构过程中，中国必须打好五张牌。其中，市场是王牌，产业链是王牌中的王牌，国际化、法治化、市场化的营商环境是一个基本牌，核心技术补齐短板是关键牌，深化改革开放是中国永远的底牌。</section><section font-size:17px;text-align:justify;white-space:normal;line-height:28px;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">疫情之下，“产业链去中国化”、“从中国撤资”、“脱钩论”等论调甚嚣尘上。国内对疫情引发产业链搬迁的担忧也不绝于耳。</section><section font-size:17px;text-align:justify;white-space:normal;line-height:28px;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">疫情之下，全球产业链会发生怎样的重构？产业链会撤出中国吗？如何维护和确保中国产业链的完整通畅？</section><section font-size:17px;text-align:justify;white-space:normal;line-height:28px;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">围绕着这些问题，中国国际经济交流中心副理事长黄奇帆在5月27日晚上的浦山讲坛上发表了题为<strong>“</strong><strong>全球产业链重构与中国应对</strong><strong>”</strong>的演讲。</section><section font-size:17px;text-align:justify;white-space:normal;line-height:28px;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">黄奇帆强调，当期中国制造企业面临的产业链阻断、出口订单减少以及由此而来的生产停摆主要是疫情造成的，与国外政客叫嚣的脱钩及撤资关系不大。&nbsp;</section><section font-size:17px;text-align:justify;white-space:normal;line-height:28px;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\"><strong>疫情之下，全球产业链面临重新洗牌，但这表现为全球产业链的结构性重构，而并非搬迁式重构。</strong></section><section font-size:17px;text-align:justify;white-space:normal;line-height:28px;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\"><strong>全球产业链将在市场规律的引导下，向垂直整合、更多元化、更具韧性的方向变迁，并不会像西方少数政客所希望的那样出现与中国的脱钩。</strong></section><section font-size:17px;text-align:justify;white-space:normal;line-height:28px;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">在黄奇帆看来，产业链从中国搬迁回美国存在不可逾越的五大困难：</section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\"><strong>其一，产业链重建所需要的资本投入难以保障；</strong></section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\"><strong>其二，产业重建的配套产业集群在美国无法轻易建立；</strong></section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\"><strong>其三，产业工人的成本与素质难以平衡；</strong></section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\"><strong>其四，美国以服务业为主、制造业占比仅13.5%的经济结构不利于制造业发展；</strong></section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\"><strong>其五，制造业发展的基础设施也难以配套。</strong></section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">他援引摩根士丹利的报告指出，经此一疫，欧美经济估计需要两年以上才能恢复元气，跨国企业未来一段时间的重中之重是保留现金、减少投资，而非搬迁产业链带来新的资本开支；中国在疫情之下展现出高效的管理能力，加上中国制造业产业链集群无可替代的优势，<strong>使得这次危机之后，中美贸易摩擦以来出现的产业链搬迁的苗头反而出现了明显的放缓趋势。</strong>黄奇帆表示，中国本土具有超大的市场规模，近几十年在中国投资的外资企业70%以上的产品是在中国市场销售的，这些企业更不会迁出中国。他指出，中国制造业需要扬长避短，把握住全球产业链重构过程中的机遇。</section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">其一，中国要健全产业链，补齐短板，拥有产业链集群是中国制造业的杀手锏，但要警惕在关键核心环节被人“一剑封喉”；</section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">其二，启动国内经济循环，鼓励出口型企业转向内销，他建议对出口转内销的产品应视同出口，不收增值税，或同样享受出口退税的优惠；</section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">其三，鼓励传统产业数字化转型，用新技术开发国内市场；</section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">其四，发挥跨境电商作用，10年以后，1/3的贸易量会通过跨境电商来完成，要增强中国跨境电商平台服务不同国家市场尤其是“一带一路”沿线国家的能力；</section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">其五，努力扩大进口贸易总额，实现进出口平衡发展，他建议通过降低关税，把2.1万亿美元的进口逐渐上升到2.6万亿，成为世界第一大进口国，从而减少贸易摩擦，并在商品定价权与人民币贸易清算中掌握主动。</section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">黄奇帆认为，<strong>在全球产业链重构过程中，市场是王牌，产业链是王牌中的王牌，国际化、法治化、市场化的营商环境是一个基本牌，核心技术补齐短板是关键牌，深化改革开放是中国永远的底牌。</strong></section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">中国必须打好这五张牌，这不仅能促进中国经济发展，还能用实际行动回应西方政客的外资撤资论，逆全球化等言论，中国也一定会突破技术封锁，补齐产业链短板，将中国制造的产业链集群打造成世界上最具竞争力的产业链集群。</section><p style=\"margin-bottom: 20px; border: none; color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245) !important;\"><img class=\"rich_pages\" data-ratio=\"0.5703971119133574\" data-s=\"300,640\" src=\"https://mmbiz.qpic.cn/mmbiz_png/a9WLd8KT642s09pgMmiaiaoMzEhRK6tePWpLRBsFcfq0vhtgVgZOr6wR6QnMqyCicniaEDsMHWiaQdFdODgct3G4YgA/640?wx_fmt=png\" data-type=\"png\" data-w=\"554\" style=\"border-width: 0px; border-style: initial; max-width: 100%; text-align: center; height: auto !important;\"></p><p style=\"margin-bottom: 20px; border: none; color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245) !important;\">在疫情带来的全球危机下，美国等国的政客针对中国提出了“撤资中国”，“产业链去中国化”，“脱钩论”等观点，并做了一系列的小动作。我们要保持定力，以稳定谋发展，以创新寻找出路，以开放拓展市场，不惧怕西方少数势力对中国的敌视，通过练好内功，广交朋友，努力抓住全球产业链重构中的机遇。为此我在这里从三个方面分析这个问题。</p><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\"><strong>产业链搬迁回美国五大困难不可逾越</strong></section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\"><strong>第一方面，市场是配置资源的最有效手段。脱钩、制造业外迁等都不符合市场规律，只不过是一些政客们的主观臆想。</strong>当前全球水平分工的产业链布局和供应链结构是全球生产要素以市场化方式自由流动的最优化配置，在疫情发生前具有相对的稳定性，<strong style=\"font-family: 阿里巴巴普惠体, serif; font-size: 16px; letter-spacing: 0.1px; color: rgb(0, 0, 0);\">疫情发生以后虽然会打破这种稳定性，但跨国公司在全球重新配置生产要素时会更注重效率、效益和成本，疫情所带来的产业链调整也必然是要符合市场规律的，而不会以少数政客的意愿而转移。</strong>美国等外资企业如果从中国撤资，就需要转移生产基地，在美国和其他地方重新建设生产设施，寻找产业链配套上的新伙伴。这一过程对这些企业而言成本高昂，并且存在难以逾越的困难，我认为这些困难表现在5个方面：</section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>第1，产业链重建所需要的资本投入难以保障。</strong></section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">疫情已经持续了将近半年，很多企业的业务基本上处于停滞状态，现金流极其紧张，很少有制造企业能够依靠自身的力量投资重建工厂。<strong>美国说要给撤资搬迁的工厂帮助，其实也就是补贴搬迁费，这难以给予这类企业相应的投资全额补贴。</strong><strong>而资本市场也因为企业业绩下滑失去了为搬迁这些企业融资的能力。</strong>所以仅仅为了政治目的，而让企业冒着资金链断裂、甚至破产的风险是不符合市场规律的，也是不合理的，企业是不会跟进的。</section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>第2，产业重建的配套产业集群无法轻易建立。</strong></section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">如果一家企业迁回美国，不仅仅是一家龙头企业的迁移，还必须要有产业链上企业集群的配套跟进。在制造业分工如此细致的市场环境下，一家制造业企业通常都有成百上千个配套企业，这些配套企业大多不可能搬迁到美国，<strong>而失去原有配套企业会导致搬迁企业产业链断裂，制造成本急剧上升，这也是不符合市场规律的。</strong>正是基于这一点考虑，特朗普三年前就要求库克把苹果的生产基地从中国搬迁回美国，库克明确地多次表态，这是不可能的。疫情前三年，他都没搬动，疫情后，现在状态下再要搬迁是更加困难。</section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>第3，产业工人的成本素质难以平衡。</strong></section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">制造企业的全球选址不仅要考虑选址地的劳动力成本，还要考虑劳动力素质。与中国产业工人相比，欧美劳动力成本较高，东南亚等劳动力成本尽管比我们低，但工人的基本素质比我们差。<strong>中国经过近40年的工业化、信息化进程，产业工人既有较高素质，同时在成本上还有比较优势。</strong><strong>中国包括农村在内的所有年轻人，高中毕业、中专毕业的教育普及程度已经达到90%，所以在这方面我们素质也是相对较好的。</strong></section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>第4，美国的经济结构制约制造业发展。</strong></section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">想要发展某些产业，不仅要考虑政府机构的主观意愿，还要考虑国家的经济基础，包括金融结构、经济结构、产业结构等等。<strong>美国的产业结构中超过80%是包括金融业在内的服务业，工业制造只占13.5%。</strong><strong>那么它的工业制造品大量依靠进口，它的产业结构并不适合发展制造业。甚至从金融角度讲，正是因为大量工业品进口，才能够通过进口支付把美元撒向全球，获取全球的造币税。</strong>所以在这个意义上讲，美国如果自己去搞大量的制造业，美元作为全球霸权的货币地位将会受到影响。</section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>第5，制造业发展的基础设施也难以配套。</strong></section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">总体上看，美国的基础设施还是优越的，但是这些设施往往都是服务于第三产业发达的城市人群的，<strong>而在服务于工业的铁路、港口、信息网络以及工业区所需要的我们所谓的“七通一平”等基础设施上，由于美国这些年工业制造业的衰退，已经变得很不完全、很不完备。</strong></section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">短时期建设这些设施，需要政府或者企业天量的投资，这也是基本不可能实现的。比如通信，美国的通信设施，不管是4G还是3G的基站，包括现在要搞的5G基站，在大城市可以，但到了郊区——所谓“搞工业”的地方——其通信能力就差得太远，这是因为美国电信公司是私人的，对于通信密度不够高的、投入产出低的地方，他们不愿意去投资。</section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\"><strong>所以整个美国4G基站只有40多万个，而中国有460万个，我们双方的国土面积是差不多的，它的基础设施是比较薄弱的。</strong>综上所述，<strong>全球产业链的重新洗牌，并不会像西方少数政客所希望的那样出现与中国脱钩，而是要在市场规律的作用下，向垂直整合的方向，更多元化的、更具韧性的方向发展。</strong></section><p font-size:17px;white-space:normal;text-align:center;\"=\"\" style=\"margin-bottom: 0px; border: none; color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; text-align: center; clear: both; background-color: rgb(245, 245, 245) !important;\"><img class=\"rich_pages\" data-ratio=\"0.5747126436781609\" data-s=\"300,640\" src=\"https://mmbiz.qpic.cn/mmbiz_png/a9WLd8KT643OjwzppAFxDtyK3CTsA5elnFF6NXmFicNibIXx69bENNUsia2VkRqVC2oIiaibwlZTiaqALsSIOdVibdvibg/640?wx_fmt=png\" data-type=\"png\" data-w=\"522\" style=\"border-width: 0px; border-style: initial; max-width: 100%; height: auto !important;\"></p><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">中国在全球产业链中具有举足轻重的地位，中国制造的优势已经被全球产业界所承认，既有完整的工业体系和完备的工业基础设施，又具有配套齐全、综合成本较低的优势，也具备了支撑全球产业链变革的基础。<br></section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">此外，中国本土具有超大的市场规模，<strong>这几十年投资在中国的外资企业，其产品的70%以上是在中国市场上销售的，剩余30%是外资企业生产出来出口的，这个意思就是说如果撤离中国，对这些在中国的外资企业来说，等于丢弃了他们70%的市场份额，这也是确保全球产业链留在中国的决定性因素。</strong></section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\"><strong>疫情放缓了贸易战以来的产业链搬迁苗头</strong><strong>第二方面，疫情之下，全球产业链表现为结构性重构，而并非搬迁式重构。</strong>最近20年，世界制造业的发展，形成了全球产业链的水平分工结构，但是这种水平分工导致产业链环节过多，运输距离过长，也会造成物流成本高、运输时间长，从而增加全球产业链断裂的风险。一旦遇到自然灾害、社会动荡、新冠疫情等全球性危机，就会打破产业链平衡，从而给全球制造业带来灾难性的冲击。</section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">面对这种脆弱性，<strong>疫情之后，产业链重构最合理的方向是让这种产业分工能够在亚洲、非洲、欧洲、美洲某些地域聚集成垂直整合的产业链集群。</strong><strong>产业链集群是在一定地域内，既做到全球化水平分工，又实现垂直整合的生产关系，是提高全球产业链抗风险能力的产物。</strong><strong>产业链集群的结构性重构，要让全球最优秀的企业聚集到具有一定产业基础的某些区域，产品收益仍然是由各参与国的企业分享，所以它也是国际化水平分工的。</strong></section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">当前担心疫情引发产业链搬迁之声不绝于耳。摩根士丹利公司最近有份报告，我看了以后深以为然。这份报告指出，通过与产业链上的实际决策者、跨国企业主们的交流，<strong>报告发现这次危机其实会放慢贸易战以来所谓的产业链搬迁趋势，</strong>这个非常重要：贸易战的时候，也就是疫情之前，有一批企业在贸易摩擦的鼓动下的确有搬迁出中国的苗头，但是疫情之下，这种搬迁需求反而放慢了，甚至停顿了下来。这主要有两个原因：</section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>第一，搬迁意味着新投资，但在全球衰退的阴霾下，无人愿意再投资。</strong></section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">经此一疫，欧美经济估计需要两年以上才能恢复元气。中国以外的拉美、东欧、东南亚新兴市场也具有薄弱环节，风险很高，容易被疫情、汇率、债务等因素引发连锁反应，增加市场风险。因此跨国企业未来一段时间的重中之重是保留现金，减少投资，而不是搬迁带来的新资本开支。摩根士丹利的调研发现，<strong>原本一些公司在疫情前打算在中国以外投资设新厂，或者在本国加大自动化投入，这些意向当前纷纷被延期。</strong></section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>第二，中国制造业产业链集群上的优势是无可替代的。</strong></section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">以TMT产业链为例，<strong>全球龙头企业几乎都认为中国在复工中展现出的管理能力进一步验证了它相对于其他新兴市场的制造业优势。</strong><strong>在封城之后仅仅两个月后，中国就控制住了疫情，生产能力几乎满血复活，不论是红黄绿码技术应用，还是体温、口罩、食堂隔断等公共卫生管理，以及员工的配合度，都远胜于其他潜在搬迁目的地，</strong>比如东南亚等地目前正经历更坎坷的生产停摆、供应脱臼的状态。</section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">还有一点在跨国企业的调研中非常明显，就是疫情促使下一阶段产业更重视云服务、物联网、远程服务等数字基建。<strong>中国恰巧正在5G、数据中心、工业互联网等数字基础设施建设上加速，中国未来的基础设施正在得到加强，而非削弱。</strong>所以这一次全球产业重构一定不是简单的搬迁，而是根据先进生产力发展的需要，以及全球各地所形成的基础设施、营商环境等生产要素进行结构性的重新配置，并基于此创新出产业链集群垂直整合的产业结构。在这一点上，我相信跨国公司企业家的理性，而不会跟着政客们的叫嚣变成一种莫名其妙的潮流，他们一定会理性地布局新的产业链、推动全球产业链结构性重构。</section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">对于中国的制造企业来说，应该清楚地认识到，<strong>目前产业链阻断和进出口订单的减少而导致的生产停摆主要是疫情造成的，与所谓的脱钩和撤资关系并不大。</strong><strong>我们应该对自己的优势有底气，有信心，不要放大自己的困难。好像现在出现的问题都是美国政客们叫嚣的脱钩造成的，好像疫情对我们带来的冲击倒是问题不大。</strong>所以我们要审时度势，重新思考全球产业链布局的方向，突出中国在制度上的优势，进一步夯实产业链集群化发展的基础设施，积极布局基于新技术的产业生态，推进传统产业的数字化转型。</section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\"><strong>中国要打好“五张牌”</strong><strong>第三方面，中国制造业在全球产业链重构过程中的机遇。我这里想讲五条措施。</strong></section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>第一，健全产业链，补齐短板。</strong></section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">我们产业链上有一些短板，有些甚至是致命的短板、容易被人家“一剑封喉”的短板。一旦面对不可控的政治或自然因素，产业链存在断裂的危险。所以面对疫情下的全球产业链重构，我们应该<strong>倒逼自己尽全力将产业链中的一部分举足轻重的零部件环节实现本土化，运用科技创新实现技术和工业突破，以产顶进。</strong><strong>拥有产业链集群是中国制造业发展的杀手锏</strong>，越是在当下的全球产业发展格局下，越要健全产业链，抓住关键问题，补齐短板，凸显劳动力成本、供应链成本、营商环境等优势，完善产业链配套设施，吸引更多全球优秀企业加入我们的产业链集群，用更大的开放抵御“去中国化”的错误思潮。</section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>第二，启动国内经济循环，鼓励出口型企业转向内销。</strong></section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">中国去年出口了2.6万亿美元，随着世界疫情的扩张，今年一季度我们的出口额降低了11.4%。第二季度的情况应该会更差。因为一季度的时候，世界上其他国家的疫情还没那么严重，他们的生产还在运行，还在采购我们的货；但是二季度，全球很多国家进入了“瘫痪”状态，它们对中国的进口正在减少，出口订单就会大量丢失。</section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\"><strong>在全球疫情可能还会持续较长时间的情况下，这些出口企业会出现订单长时期骤减，资金链断裂的极度困难。</strong></section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">中国的出口涉及到国际上的疫情治理，现在全球的新冠疫情确诊数已经超过500万，我认为到6月底可能突破800万，全年会在1500万人以上。在这个情况下，我们要针对长周期订单低迷的状态制定策略、改变策略，加快启动国内经济循环，鼓励出口型企业把自己的产品根据国内市场的需要进行改造，扩大内销份额。需要注意的是，我们的出口是退税的，很多产品本来是在不含税的成本下开展出口业务的，现在内销的话如果去收它13%增值税或者其他税的话，它的成本上可能不适应国内销售，<strong style=\"color: rgb(0, 0, 0); font-family: 阿里巴巴普惠体, serif; font-size: 16px; letter-spacing: 0.1px;\">所以对于这部分出口转内销的企业，可以在一个时间内给予特殊政策：出口转内销，视同出口，不收增值税，或同样享受出口退税的政策。</strong></section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>第三，鼓励传统产业数字化转型，用新技术开发国内市场。</strong></section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">中国的人口基数、自然资源、GDP水平决定了中国自身市场巨大，各行各业都存在着大量的基于新技术的市场空间。比如我们现在能源行业，中国每年要进口大约4.5亿吨石油，我们自己生产了2亿多吨，总的消耗6亿多吨。</section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">随着中国经济发展，能源需求还会进一步增长，也许以后要增加到7亿吨、8亿吨、9亿吨，如果增长了以后，增加的订单都依赖进口，变成一年4.5亿、6.5亿、7.5亿的进口，这样的能源结构是不安全的。而事实上，中国具有世界上最丰富的煤炭储量，每年的煤炭产能在50亿吨，实际的煤炭产量现在去库存压在38亿吨-40亿吨，也就是说我们的煤炭产能是富裕的、闲置的。如果用煤炭来代替石油，作为化工原料是有发展空间的。无非大家是感觉煤炭污染严重，比石油化工污染要大。那么怎么样努力研发煤炭的清洁利用技术？在清洁工艺的前提下，如何发展煤制气，煤制油、煤化工？比如神华集团在宁夏搞的煤制气、煤制油是一流水平的，而且我去看过它的工艺流程，都达到世界先进水平。我觉得这些企业应该发扬光大。如果我们中国用多出的10亿吨煤炭搞煤化工、煤制油、煤制气，那么我们原油的需求量可能就省掉1亿多吨-2亿吨。再比如，截止到2019年6月，中国汽车每100人保有17.9辆，与发达国家相比——他们一般是每100人30辆汽车——我们还有很大的上升空间，尤其是随着新能源汽车的普及，以及汽车产品自身向数字化平台的变革，汽车产业还有巨大的成长空间，并将极大地带动中国城市基础设施的发展。</section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>第四，重视网络空间的市场价值，充分发挥跨境电商的作用。</strong></section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">疫情期间阿里巴巴、京东这类电商企业营业额没有出现下降，反而逆势上扬，充分说明网络空间形成的市场与传统的市场有很大不同，在疫情期间前者能够部分避免因为物理隔离带来的交易障碍，所以要进一步发挥中国在跨境电商平台上的优势，增强跨境电商平台服务不同国家市场的能力，尤其是在“一带一路”沿线国家，通过帮助他们加入跨境电商平台，增加中国的贸易进出口量。</section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">可以做一个判断：<strong>10年以后，全世界的货物贸易量1/3是传统贸易的形式，1/3是我们过去几十年形成的加工贸易，还有1/3会是通过跨境电商的贸易来完成。所以这地方潜力巨大。</strong>此外，我们国内电子商务可以说是世界最发达的，但这些电商的业务量百分之八十几都是国内贸易，而国际贸易只占阿里巴巴的全部贸易量的10%左右。阿里巴巴国内的贸易总规模比亚马逊要大得多，但亚马逊网络平台上的国际贸易量是阿里巴巴的4倍多，说明我们的跨境电商做的还不够，把这一块做上去也会拓展我们的贸易市场。</section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>第五，努力扩大进口贸易总额，实现进出口平衡发展。</strong></section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">去年中国4.6万亿美元进出口，其中差不多2.5万亿是出口，2.1万亿是进口。我们一方面进出口贸易是世界上最大的，出口贸易也是世界最大的，这容易引起贸易摩擦。美国是世界上最大的贸易进口国2.6万亿，中国进口额与其差5000亿美元，<strong>如果我们通过降低关税、扩大进口把2.1万亿美元的进口逐渐上升到2.6万亿，就会成为世界第一大进口国，这要比世界第一大出口国更为重要。</strong></section><p font-size:17px;white-space:normal;text-align:center;\"=\"\" style=\"margin-bottom: 0px; border: none; color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; text-align: center; clear: both; background-color: rgb(245, 245, 245) !important;\"><img class=\"rich_pages\" data-ratio=\"0.5613718411552346\" data-s=\"300,640\" src=\"https://mmbiz.qpic.cn/mmbiz_png/a9WLd8KT643OjwzppAFxDtyK3CTsA5elV8Xbyu2ibC8ziby9KWLib3DEiaV2tgictnv0GMS1V8gwyEpiahTOKP4pjn4Q/640?wx_fmt=png\" data-type=\"png\" data-w=\"554\" style=\"border-width: 0px; border-style: initial; max-width: 100%; height: auto !important;\"></p><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\"><strong>其一，这会减少与其他国家的贸易摩擦。</strong>大家一看你是世界最大的进口国都会争相与你合作，从而收获更多的全球贸易伙伴。进口国对他们来说，就是一个市场的衣食父母，他们会成为中国更好的贸易伙伴。<br></section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\"><strong>其二，进口大国在很多领域更容易拥有商品定价权，这是不言而喻的。</strong></section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\"><strong>其三，进口大国的货币在全球贸易中也会升格为商品计价的货币，变成硬通货。</strong></section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\"><strong>其四，进口大国会推动跨境人民币贸易清算</strong><strong>，</strong>使得一部分进口产品直接使用人民币付费，这样也能更好的平衡进出口过程的外汇收支。</section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\"><strong>其五，进口产品的增加还会带动老百姓消费结构的变化，带动制造业产业结构、工业结构的升级调整。</strong>这是中国经济发展到现阶段调整产业结构所应该看重的。</section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\">5月14号中共中央政治局常委会召开会议，在此次会议上，中央首次提出构建国内国际双循环相互促进的新发展格局，为稳定经济社会发展作出新谋划、新布局，也为我们中国的企业在全球产业链重构中指明了方向。</section><section font-size:17px;text-align:justify;white-space:normal;\"=\"\" style=\"color: rgb(51, 51, 51); font-family: &quot;Microsoft YaHei&quot;; background-color: rgb(245, 245, 245); margin-bottom: 20px;\"><strong>总之，在参与全球产业链重构的过程中，市场是王牌，产业链是王中王牌，营商环境的国际化、法治化、市场化是一个基本牌，核心技术创新补齐短板是关键牌，深化改革开放是我们永远的底牌。</strong>打好这5张牌不仅能够促进中国经济发展，还能够用实际行动回应西方政客的外资撤资论，逆全球化等言论，中国的企业也一定会突破技术封锁，补齐产业链短板，中国制造的产业链集群一定会成为世界上最具竞争力的产业链集群。</section><p>转载：文章来源易容网&nbsp; &nbsp;(www.mlcc1.com)</p>', 0, 1, 1656575007, 1656575027, 1659081274);
INSERT INTO `app_news` (`news_id`, `category_id`, `author`, `title`, `img`, `desc`, `content`, `sort`, `status`, `news_time`, `created_at`, `updated_at`) VALUES (5, 2, 'admin', '京瓷AVX元件公司收购罗门株式会社的钽和聚合物电容器业务资产', '/upload/newsImg/20220729/1659080673_kyocera-avx-logo.jpg', '', '<h6 style=\"margin-top: 15px; margin-bottom: 2px; padding-bottom: 2px; border: 0px; outline: 0px; font-size: 1.2996em; vertical-align: baseline; background: 0px 0px rgb(255, 255, 255); line-height: 1.2; font-family: &quot;Noto Sans&quot;; font-weight: 400; color: rgb(51, 51, 51);\"><p style=\"margin-bottom: 5px; padding-top: 5px; padding-bottom: 5px; border: 0px; outline: 0px; font-size: 12px; vertical-align: baseline; background-image: initial; background-position: 0px 0px; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; color: rgb(0, 0, 0);\">FOUNTAIN INN, S.C. (March 4, 2022) –&nbsp;<a href=\"https://www.kyocera-avx.com/\" style=\"border: 0px; outline: 0px; vertical-align: baseline; background: 0px 0px; color: rgb(0, 115, 157);\">KYOCERA AVX</a>, a leading global manufacturer of advanced electronic components engineered to accelerate technological innovation and build a better future, is set to acquire ROHM Semiconductor’s tantalum and polymer capacitor business assets. The two companies recently reached a final agreement, which states that ROHM Semiconductor (ROHM Co., Ltd.) will transfer its tantalum and polymer capacitor business assets — including all of its tantalum and polymer capacitor manufacturing lines and relevant intellectual property — to KYOCERA AVX. The transfer is scheduled to be executed on August 5, 2022, and ROHM will continue to produce tantalum and polymer capacitor products and supply them to KYOCERA AVX until all relevant production lines have been successfully transferred to the KYOCERA AVX manufacturing site. This will ensure a continuous supply for ROHM customers and immediately increase the already extensive selection of electrolytic capacitor solutions available to KYOCERA AVX customers.</p><p style=\"margin-bottom: 5px; padding-top: 5px; padding-bottom: 5px; border: 0px; outline: 0px; font-size: 12px; vertical-align: baseline; background-image: initial; background-position: 0px 0px; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; color: rgb(0, 0, 0);\">“KYOCERA AVX is excited to announce the acquisition of ROHM Semiconductor’s tantalum and polymer capacitor business assets and to further expand our already extensive portfolio of electrolytic capacitor solutions,” said Johnny Sarvis, CEO of KYOCERA AVX. “KYOCERA AVX is the leading global supplier of tantalum capacitors, as well as the largest supplier of high-reliability manganese dioxide (MnO2) solid tantalum capacitors for medical, military, and aerospace applications. In addition, we have four global manufacturing plants to ensure we can deliver the flexibility and capacity required by these demanding markets.”</p><p style=\"margin-bottom: 5px; padding-top: 5px; padding-bottom: 5px; border: 0px; outline: 0px; font-size: 12px; vertical-align: baseline; background-image: initial; background-position: 0px 0px; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; color: rgb(0, 0, 0);\">“Our polymer capacitors also offer significant advantages compared to others’ technologies, including high capacitance ratings in small, low-profile form factors, low ESR, stability over time, and a benign failure mode under recommended use conditions,” Sarvis continued. “In addition, they are environmentally friendly, lead-free, halogen-free, and RoHS-compliant and are ideal for use in commercial, industrial, automotive, and aerospace applications including smartphones, tablets, PCs, telecommunication systems, and solid-state drives.”</p><p style=\"margin-bottom: 5px; padding-top: 5px; padding-bottom: 5px; border: 0px; outline: 0px; font-size: 12px; vertical-align: baseline; background-image: initial; background-position: 0px 0px; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; color: rgb(0, 0, 0);\">“KYOCERA AVX also has an open and progressive policy on ethical supply and is the first tantalum capacitor supplier to comply with OECD guidelines and legislation on conflict minerals, which are globally impactful achievements that we are incredibly proud of,” said Sarvis.</p><p style=\"margin-bottom: 5px; padding-top: 5px; padding-bottom: 5px; border: 0px; outline: 0px; font-size: 12px; vertical-align: baseline; background-image: initial; background-position: 0px 0px; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; color: rgb(0, 0, 0);\">KYOCERA AVX’s portfolio of&nbsp;<a href=\"https://www.kyocera-avx.com/products/tantalum/\" style=\"border: 0px; outline: 0px; vertical-align: baseline; background: 0px 0px; color: rgb(0, 115, 157);\">electrolytic capacitors</a>&nbsp;includes an extensive selection of&nbsp;<a href=\"https://www.kyocera-avx.com/products/tantalum/high-reliability/\" style=\"border: 0px; outline: 0px; vertical-align: baseline; background: 0px 0px; color: rgb(0, 115, 157);\">high-reliability</a>,&nbsp;<a href=\"https://www.kyocera-avx.com/products/tantalum/leaded/\" style=\"border: 0px; outline: 0px; vertical-align: baseline; background: 0px 0px; color: rgb(0, 115, 157);\">leaded</a>,&nbsp;<a href=\"https://www.kyocera-avx.com/products/tantalum/smd-tantalum-mno2/\" style=\"border: 0px; outline: 0px; vertical-align: baseline; background: 0px 0px; color: rgb(0, 115, 157);\">SMD standard tantalum MnO2</a>,&nbsp;<a href=\"https://www.kyocera-avx.com/products/tantalum/automotive/\" style=\"border: 0px; outline: 0px; vertical-align: baseline; background: 0px 0px; color: rgb(0, 115, 157);\">automotive-qualified</a>,&nbsp;<a href=\"https://www.kyocera-avx.com/products/tantalum/wet-tantalum/\" style=\"border: 0px; outline: 0px; vertical-align: baseline; background: 0px 0px; color: rgb(0, 115, 157);\">wet tantalum electrolytic</a>, and&nbsp;<a href=\"https://www.kyocera-avx.com/tantalum/smd-tantalum-mno2/high-temp/\" style=\"border: 0px; outline: 0px; vertical-align: baseline; background: 0px 0px; color: rgb(0, 115, 157);\">high-temperature tantalum capacitors</a>, and its&nbsp;<a href=\"https://www.kyocera-avx.com/products/polymer/\" style=\"border: 0px; outline: 0px; vertical-align: baseline; background: 0px 0px; color: rgb(0, 115, 157);\">portfolio of polymer capacitors</a>&nbsp;includes an extensive selection of&nbsp;<a href=\"https://www.kyocera-avx.com/polymer/smd-tantalum-polymer/standard/\" style=\"border: 0px; outline: 0px; vertical-align: baseline; background: 0px 0px; color: rgb(0, 115, 157);\">standard</a>,&nbsp;<a href=\"https://www.kyocera-avx.com/products/polymer/high-voltage/\" style=\"border: 0px; outline: 0px; vertical-align: baseline; background: 0px 0px; color: rgb(0, 115, 157);\">high-voltage</a>,&nbsp;<a href=\"https://www.kyocera-avx.com/polymer/smd-tantalum-polymer/small-case-size/\" style=\"border: 0px; outline: 0px; vertical-align: baseline; background: 0px 0px; color: rgb(0, 115, 157);\">small case size</a>,&nbsp;<a href=\"https://www.kyocera-avx.com/products/polymer/j-cap-series/\" style=\"border: 0px; outline: 0px; vertical-align: baseline; background: 0px 0px; color: rgb(0, 115, 157);\">SSD</a>,&nbsp;<a href=\"https://www.kyocera-avx.com/products/polymer/high-reliability-polymers/\" style=\"border: 0px; outline: 0px; vertical-align: baseline; background: 0px 0px; color: rgb(0, 115, 157);\">high-reliability</a>, and&nbsp;<a href=\"https://www.kyocera-avx.com/polymer/automotive-polymer-capacitors/\" style=\"border: 0px; outline: 0px; vertical-align: baseline; background: 0px 0px; color: rgb(0, 115, 157);\">automotive-qualified polymer capacitors</a>. Additionally, the recent launch of the&nbsp;<a href=\"https://www.kyocera-avx.com/products/aluminum-capacitors/\" style=\"border: 0px; outline: 0px; vertical-align: baseline; background: 0px 0px; color: rgb(0, 115, 157);\">aluminum electrolytic capacitor</a>&nbsp;portfolio of standard wet, polymer, and hybrid capacitors allow customers more options for larger bulk capacitance solutions.</p><p style=\"margin-bottom: 5px; padding-top: 5px; padding-bottom: 5px; border: 0px; outline: 0px; font-size: 12px; vertical-align: baseline; background-image: initial; background-position: 0px 0px; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; color: rgb(0, 0, 0);\">For more information about KYOCERA AVX, please visit&nbsp;<a href=\"https://www.kyocera-avx.com/\" style=\"border: 0px; outline: 0px; vertical-align: baseline; background: 0px 0px; color: rgb(0, 115, 157);\">https://www.kyocera-avx.com/</a>, email&nbsp;<a href=\"mailtinquiry@kyocera-avx.com\" style=\"border: 0px; outline: 0px; vertical-align: baseline; background: 0px 0px; color: rgb(0, 115, 157);\">inquiry@kyocera-avx.com</a>, follow them on&nbsp;<a href=\"https://www.linkedin.com/company/kavxcorp/\" rel=\"noopener\" target=\"_blank\" style=\"border: 0px; outline: 0px; vertical-align: baseline; background: 0px 0px; color: rgb(0, 115, 157);\">LinkedIn</a>,&nbsp;<a href=\"https://twitter.com/kavxcorp\" rel=\"noopener\" target=\"_blank\" style=\"border: 0px; outline: 0px; vertical-align: baseline; background: 0px 0px; color: rgb(0, 115, 157);\">Twitter</a>, and&nbsp;<a href=\"https://www.instagram.com/kavxcorp/\" rel=\"noopener\" target=\"_blank\" style=\"border: 0px; outline: 0px; vertical-align: baseline; background: 0px 0px; color: rgb(0, 115, 157);\">Instagram</a>, like them on&nbsp;<a href=\"https://www.facebook.com/kavxcorp\" rel=\"noopener\" target=\"_blank\" style=\"border: 0px; outline: 0px; vertical-align: baseline; background: 0px 0px; color: rgb(0, 115, 157);\">Facebook</a>, call 864-967-2150, or write to One AVX Boulevard, Fountain Inn, S.C. 29644.</p><p style=\"margin-bottom: 5px; padding-top: 5px; padding-bottom: 5px; border: 0px; outline: 0px; font-size: 12px; vertical-align: baseline; background-image: initial; background-position: 0px 0px; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; color: rgb(0, 0, 0);\">About ROHM<br>Founded in 1958, ROHM provides LSI and discrete semiconductors characterized by outstanding quality and reliability for a broad range of markets, including automotive, industrial and consumer market via its global development and sales network. In the power and analog field, ROHM proposes the suitable solution for each application with power devices such as SiC, driver ICs to maximize their performance, and peripheral components such as transistors, diodes and resistors. Further information on ROHM can be found at&nbsp;<a href=\"https://www.rohm.com/\" rel=\"noopener\" target=\"_blank\" style=\"border: 0px; outline: 0px; vertical-align: baseline; background: 0px 0px; color: rgb(0, 115, 157);\">https://www.rohm.com/</a></p><div><br></div><div class=\"single-postmetadata-divider-bottom\" style=\"border: 0px; outline: 0px; font-size: 12px; vertical-align: baseline; background-image: initial; background-position: 0px 0px; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; color: rgb(0, 0, 0);\"></div></h6>', 0, 1, 1656663786, 1656663806, 1659080749);
INSERT INTO `app_news` (`news_id`, `category_id`, `author`, `title`, `img`, `desc`, `content`, `sort`, `status`, `news_time`, `created_at`, `updated_at`) VALUES (6, 2, 'admin', 'Tantalum Capacitors', '/upload/newsImg/20220729/1659080148_ceramic-tantalum-capacitors-125x125_c.jpg', '', '<p style=\"margin-bottom: 16.5px; border: none; color: rgb(102, 102, 102); background-color: rgb(255, 255, 255); list-style: none; box-sizing: border-box; outline: 0px; text-size-adjust: none; font-family: 微软雅黑, &quot;microsoft yahei&quot;, helvetica, tahoma, sans-serif; text-align: justify; text-indent: 32px;\">KYOCERA AVX is the number one tantalum capacitor supplier with four manufacturing plants worldwide, which provides flexibility and capacity for the demanding electronic industry. We are the global leader in MnO<sub style=\"color: rgb(51, 51, 51); font-family: &quot;Noto Sans&quot;; text-align: start; text-indent: 0px;\">2</sub>&nbsp;solid tantalum technologies such as smallest case size MnO<sub style=\"color: rgb(51, 51, 51); font-family: &quot;Noto Sans&quot;; text-align: start; text-indent: 0px;\">2</sub>, highest temperature capabilities up to 230°C and lowest DCL product offering.</p><p style=\"margin-bottom: 5px; padding-top: 5px; padding-bottom: 5px; border: 0px; outline: 0px; font-size: 15.5952px; vertical-align: baseline; background: 0px 0px rgb(255, 255, 255); color: rgb(51, 51, 51); font-family: &quot;Noto Sans&quot;;\"></p><p style=\"margin-bottom: 5px; padding-top: 5px; padding-bottom: 5px; border: 0px; outline: 0px; font-size: 15.5952px; vertical-align: baseline; background: 0px 0px rgb(255, 255, 255); color: rgb(51, 51, 51); font-family: &quot;Noto Sans&quot;;\">KYOCERA AVX has the industry leading position in high reliability tantalum capacitors and is the largest supplier of high reliability solid tantalum capacitors for medical and military/aerospace applications with the industry’s widest range of medical, COTS-Plus, MIL spec and space level products. KYOCERA AVX Conformal technology offers leading edge solutions for audio and infrastructure applications.</p><p style=\"margin-bottom: 5px; padding-top: 5px; padding-bottom: 5px; border: 0px; outline: 0px; font-size: 15.5952px; vertical-align: baseline; background: 0px 0px rgb(255, 255, 255); color: rgb(51, 51, 51); font-family: &quot;Noto Sans&quot;;\">KYOCERA AVX has an open and progressive policy on ethical supply and is first to be in compliance with OECD guidelines and legislation on conflict materials.</p><p><br></p>', 0, 1, 1656663825, 1656663838, 1659080150);
INSERT INTO `app_news` (`news_id`, `category_id`, `author`, `title`, `img`, `desc`, `content`, `sort`, `status`, `news_time`, `created_at`, `updated_at`) VALUES (7, 3, 'admin', '【集成电路】纳米制程是什么？', '/upload/newsImg/20220708/1657249515_202232314410198.jpg', '', '<p style=\"margin-bottom: 0px; border: none; color: rgb(102, 102, 102); list-style: none; background-color: rgb(255, 255, 255); box-sizing: border-box; outline: 0px; text-size-adjust: none; font-family: 微软雅黑, &quot;microsoft yahei&quot;, helvetica, tahoma, sans-serif; text-align: justify;\">三星以及台积电在先进半导体制程打得相当火热，彼此都想要在晶圆代工中抢得先机以争取订单，然而半导体制程中所描述的那些数字究竟有何意义？指的又是哪个部位？而在缩小制程后又将来带来什么好处与难题？以下我们将就纳米制程做简单的说明。</p><p style=\"margin-bottom: 0px; border: none; color: rgb(102, 102, 102); list-style: none; background-color: rgb(255, 255, 255); box-sizing: border-box; outline: 0px; text-size-adjust: none; font-family: 微软雅黑, &quot;microsoft yahei&quot;, helvetica, tahoma, sans-serif; text-align: justify;\">　　纳米到底有多细微？</p><p style=\"margin-bottom: 0px; border: none; color: rgb(102, 102, 102); list-style: none; background-color: rgb(255, 255, 255); box-sizing: border-box; outline: 0px; text-size-adjust: none; font-family: 微软雅黑, &quot;microsoft yahei&quot;, helvetica, tahoma, sans-serif; text-align: justify;\">　　在开始之前，要先了解纳米究竟是什么意思。在数学上，纳米是 0.000000001 公尺，但这是个相当差的例子，毕竟我们只看得到小数点后有很多个零，却没有实际的感觉。如果以指甲厚度做比较的话，或许会比较明显。</p><p style=\"margin-bottom: 0px; border: none; color: rgb(102, 102, 102); list-style: none; background-color: rgb(255, 255, 255); box-sizing: border-box; outline: 0px; text-size-adjust: none; font-family: 微软雅黑, &quot;microsoft yahei&quot;, helvetica, tahoma, sans-serif; text-align: center;\"><br></p><p style=\"margin-bottom: 0px; border: none; color: rgb(102, 102, 102); list-style: none; background-color: rgb(255, 255, 255); box-sizing: border-box; outline: 0px; text-size-adjust: none; font-family: 微软雅黑, &quot;microsoft yahei&quot;, helvetica, tahoma, sans-serif; text-align: justify;\">　　用尺规实际测量的话可以得知指甲的厚度约为 0.0001 公尺（0.1 毫米），也就是说试着把一片指甲的侧面切成 10 万条线，每条线就约等同于 1 纳米，由此可略为想像得到 1 纳米是何等的微小了。</p><p style=\"margin-bottom: 0px; border: none; color: rgb(102, 102, 102); list-style: none; background-color: rgb(255, 255, 255); box-sizing: border-box; outline: 0px; text-size-adjust: none; font-family: 微软雅黑, &quot;microsoft yahei&quot;, helvetica, tahoma, sans-serif; text-align: justify;\">　　知道纳米有多小之后，还要理解缩小制程的用意，缩小电晶体的最主要目的，就是可以在更小的芯片中塞入更多的电晶体，让芯片不会因技术提升而变得更大；其次，可以增加处理器的运算效率；再者，减少体积也可以降低耗电量；最后，芯片体积缩小后，更容易塞入行动装置中，满足未来轻薄化的需求。</p><p style=\"margin-bottom: 0px; border: none; color: rgb(102, 102, 102); list-style: none; background-color: rgb(255, 255, 255); box-sizing: border-box; outline: 0px; text-size-adjust: none; font-family: 微软雅黑, &quot;microsoft yahei&quot;, helvetica, tahoma, sans-serif; text-align: justify;\">　　再回来探究纳米制程是什么，以 14 纳米为例，其制程是指在芯片中，线最小可以做到 14 纳米的尺寸，下图为传统电晶体的长相，以此作为例子。缩小电晶体的最主要目的就是为了要减少耗电量，然而要缩小哪个部分才能达到这个目的？左下图中的 L 就是我们期望缩小的部分。藉由缩小闸极长度，电流可以用更短的路径从 Drain 端到 Source 端（有兴趣的话可以利用 Google 以 MOSFET 搜寻，会有更详细的解释）。</p><p style=\"margin-bottom: 0px; border: none; color: rgb(102, 102, 102); list-style: none; background-color: rgb(255, 255, 255); box-sizing: border-box; outline: 0px; text-size-adjust: none; font-family: 微软雅黑, &quot;microsoft yahei&quot;, helvetica, tahoma, sans-serif; text-align: justify;\">　　IC:纳米制程是什么？</p><p style=\"margin-bottom: 0px; border: none; color: rgb(102, 102, 102); list-style: none; background-color: rgb(255, 255, 255); box-sizing: border-box; outline: 0px; text-size-adjust: none; font-family: 微软雅黑, &quot;microsoft yahei&quot;, helvetica, tahoma, sans-serif; text-align: justify;\">　　此外，电脑是以 0 和 1 作运算，要如何以电晶体满足这个目的呢？做法就是判断电晶体是否有电流流通。当在 Gate 端（绿色的方块）做电压供给，电流就会从 Drain 端到 Source 端，如果没有供给电压，电流就不会流动，这样就可以表示 1 和 0。（至于为什么要用 0 和 1 作判断，有兴趣的话可以去查布林代数，我们是使用这个方法作成电脑的）</p><p style=\"margin-bottom: 0px; border: none; color: rgb(102, 102, 102); list-style: none; background-color: rgb(255, 255, 255); box-sizing: border-box; outline: 0px; text-size-adjust: none; font-family: 微软雅黑, &quot;microsoft yahei&quot;, helvetica, tahoma, sans-serif; text-align: justify;\">　　尺寸缩小有其物理限制</p><p style=\"margin-bottom: 0px; border: none; color: rgb(102, 102, 102); list-style: none; background-color: rgb(255, 255, 255); box-sizing: border-box; outline: 0px; text-size-adjust: none; font-family: 微软雅黑, &quot;microsoft yahei&quot;, helvetica, tahoma, sans-serif; text-align: justify;\">　　不过，制程并不能无限制的缩小，当我们将电晶体缩小到 20 纳米左右时，就会遇到量子物理中的问题，让电晶体有漏电的现象，抵销缩小 L 时获得的效益。作为改善方式，就是导入 FinFET（Tri-Gate）这个概念，如右上图。在 Intel 以前所做的解释中，可以知道藉由导入这个技术，能减少因物理现象所导致的漏电现象。</p><p style=\"margin-bottom: 0px; border: none; color: rgb(102, 102, 102); list-style: none; background-color: rgb(255, 255, 255); box-sizing: border-box; outline: 0px; text-size-adjust: none; font-family: 微软雅黑, &quot;microsoft yahei&quot;, helvetica, tahoma, sans-serif; text-align: justify;\">　　IC:纳米制程是什么？</p><p style=\"margin-bottom: 0px; border: none; color: rgb(102, 102, 102); list-style: none; background-color: rgb(255, 255, 255); box-sizing: border-box; outline: 0px; text-size-adjust: none; font-family: 微软雅黑, &quot;microsoft yahei&quot;, helvetica, tahoma, sans-serif; text-align: justify;\">　　更重要的是，藉由这个方法可以增加 Gate 端和下层的接触面积。在传统的做法中（左上图），接触面只有一个平面，但是采用 FinFET（Tri-Gate）这个技术后，接触面将变成立体，可以轻易的增加接触面积，这样就可以在保持一样的接触面积下让 Source-Drain 端变得更小，对缩小尺寸有相当大的帮助。</p><p style=\"margin-bottom: 0px; border: none; color: rgb(102, 102, 102); list-style: none; background-color: rgb(255, 255, 255); box-sizing: border-box; outline: 0px; text-size-adjust: none; font-family: 微软雅黑, &quot;microsoft yahei&quot;, helvetica, tahoma, sans-serif; text-align: justify;\">　　最后，则是为什么会有人说各大厂进入 10 纳米制程将面临相当严峻的挑战，主因是 1 颗原子的大小大约为 0.1 纳米，在 10 纳米的情况下，一条线只有不到 100 颗原子，在制作上相当困难，而且只要有一个原子的缺陷，像是在制作过程中有原子掉出或是有杂质，就会产生不知名的现象，影响产品的良率。</p><p style=\"margin-bottom: 0px; border: none; color: rgb(102, 102, 102); list-style: none; background-color: rgb(255, 255, 255); box-sizing: border-box; outline: 0px; text-size-adjust: none; font-family: 微软雅黑, &quot;microsoft yahei&quot;, helvetica, tahoma, sans-serif; text-align: justify;\">　　如果无法想像这个难度，可以做个小实验。在桌上用 100 个小珠子排成一个 10×10 的正方形，并且剪裁一张纸盖在珠子上，接着用小刷子把旁边的的珠子刷掉，最后使他形成一个 10×5 的长方形。这样就可以知道各大厂所面临到的困境，以及达成这个目标究竟是多么艰巨。</p>', 0, 1, 1656663847, 1656663863, 1657249519);
INSERT INTO `app_news` (`news_id`, `category_id`, `author`, `title`, `img`, `desc`, `content`, `sort`, `status`, `news_time`, `created_at`, `updated_at`) VALUES (8, 3, 'admin', '三星采用两大策略，在图像传感器市场挑战龙头索尼', '/upload/newsImg/20220708/1657249502_202232314419577.jpg', '', '<p style=\"margin-bottom: 0px; border: none; color: rgb(102, 102, 102); list-style: none; font-family: &quot;microsoft yahei&quot;, simsun, arial; background-color: rgb(255, 255, 255);\">积极在非存储器半导体产品发展的韩国三星电子，目前正在图形传感器市场采用两项策略，包括采用更先进制程技术，以及更具竞争力的订价策略，挑战市场龙头SONY的地位。</p><p style=\"margin-bottom: 0px; border: none; color: rgb(102, 102, 102); list-style: none; font-family: &quot;microsoft yahei&quot;, simsun, arial; background-color: rgb(255, 255, 255);\">根据韩国媒体《KoreaBusiness》报导指出，当前在图形传感器积极发展的韩国三星，正在向主要智能手机制造商推广自家行动图像传感器。特别的是，过去的竞争对手，韩国LG电子最近在旗下的智能手机产品中也采用了三星的图形传传感器。</p><p style=\"margin-bottom: 0px; border: none; color: rgb(102, 102, 102); list-style: none; font-family: &quot;microsoft yahei&quot;, simsun, arial; background-color: rgb(255, 255, 255);\"><br></p><p style=\"margin-bottom: 0px; border: none; color: rgb(102, 102, 102); list-style: none; font-family: &quot;microsoft yahei&quot;, simsun, arial; background-color: rgb(255, 255, 255);\">事实上，这两家公司目前正在就8K电视影像画质展开口水战，甚至此一争议还发展到了官司诉讼的阶段。不过，这并不影响三星的3,200万像素图像传感器被装入LG旗下智能手机V50S SynQ前置摄影镜头中的决定。</p><p style=\"margin-bottom: 0px; border: none; color: rgb(102, 102, 102); list-style: none; font-family: &quot;microsoft yahei&quot;, simsun, arial; background-color: rgb(255, 255, 255);\">另外，报导还指出，三星的系统业务部已经确定LG将成为长期稳定客户之一，如此以进一步提高图像传感器的销售状况和市场占有率。另外，包括中国小米和OPPO等主要智能手机制造商，也开始选用三星的图像传感器装置给旗下最新产品。因此，三星在图像传感器市场的市占率有望持续。</p><p style=\"margin-bottom: 0px; border: none; color: rgb(102, 102, 102); list-style: none; font-family: &quot;microsoft yahei&quot;, simsun, arial; background-color: rgb(255, 255, 255);\">有调查结果显示，SONY在2019年第1季以51.1%市占率位居图形传感器市场龙头。紧跟在后的是三星电子17.8%，Omni Vision以13.5%排名第3，之后为安森美半导体5.7%，以及SK海力士2.7%。</p><p style=\"margin-bottom: 0px; border: none; color: rgb(102, 102, 102); list-style: none; font-family: &quot;microsoft yahei&quot;, simsun, arial; background-color: rgb(255, 255, 255);\">另外，近期在智能手机安装多个镜头的高性能相机系统，再加上自驾车在辅助系统多方应用照相镜头，使图形传感器市场加速成长。三星正努力提高性能竞争力，同时专注于新技术开发。</p><p style=\"margin-bottom: 0px; border: none; color: rgb(102, 102, 102); list-style: none; font-family: &quot;microsoft yahei&quot;, simsun, arial; background-color: rgb(255, 255, 255);\">三星已于8月开始批量生产业界首个1,800万像素图像传感器，且2018年9月开发的业界首款0.7微米超紧致型行动图像传感器，已在2019年大量生产。凭藉这些优势，三星期望能进一步挑战SONY的龙头地位。</p>', 0, 1, 1656663872, 1656663885, 1657249504);
INSERT INTO `app_news` (`news_id`, `category_id`, `author`, `title`, `img`, `desc`, `content`, `sort`, `status`, `news_time`, `created_at`, `updated_at`) VALUES (9, 3, 'admin', 'Replacing Aluminum Electrolytic Capacitors With Tantalum Or Ceramic Capacitors', '/upload/newsImg/20220729/1659079927_ceramic-tantalum-capacitors-125x125_c.jpg', '', '<p style=\"margin-bottom: 0px; border: none; color: rgb(102, 102, 102); list-style: none; font-family: &quot;microsoft yahei&quot;, simsun, arial; background-color: rgb(255, 255, 255);\">Replacing Aluminum Electrolytic Capacitors with Tantalum or Ceramic Capacitors Written By: Teddy Won Abstract: Like all capacitors, electrolytics (e-caps) are based on the principle of storing energy in an electric field using a voltage applied across a dielectric. This paper discusses the basic structure and characteristics of electrolytics and shows alternates for circuit use.</p>', 0, 1, 1657355093, 1656663905, 1659079929);
INSERT INTO `app_news` (`news_id`, `category_id`, `author`, `title`, `img`, `desc`, `content`, `sort`, `status`, `news_time`, `created_at`, `updated_at`) VALUES (10, 2, 'admin', '做好汽车芯片和上游原材料保供稳价 保障产业链供应链畅通稳定', '/upload/newsImg/20220709/1657356713_wKhk3mLH8vOAXZGaAAc3gk9pzrA922.png', '', '<div>7月7日，国新办举行稳定增加汽车消费国务院政策例行吹风会，工业和信息化部装备工业一司负责人郭守刚在会上表示，将加强行业运行监测研判，做好汽车芯片和上游原材料保供稳价工作，全力保障产业链供应链畅通稳定。</div><div><br></div><div>近日，商务部、工业和信息化部、住房和城乡建设部等16部门发布《关于搞活汽车流通 扩大汽车消费的若干措施》（《若干措施》）。郭守刚表示，工信部将落实《若干措施》要求，会同相关部门进一步扩大新能源汽车推广规模。一是持续完善新能源汽车安全技术标准，提升动力电池热失控报警、安全防护、低温适应等性能水平。推动电动化与智能网联技术融合发展，开发更多适合消费者的服务功能，持续提升驾乘体验，催生更多购买需求。</div><div><br></div><div>二是营造良好使用环境。加强行业运行监测研判，做好汽车芯片和上游原材料保供稳价工作，全力保障产业链供应链畅通稳定。落实国务院稳定增加汽车等大宗消费要求，鼓励有条件的地方出台有含金量的促消费政策。抓紧研究明确新能源汽车车购税优惠延续等支持政策，优化“双积分”管理办法，做好与补贴退坡的有效衔接。开展好新一轮新能源汽车下乡活动，组织实施公共领域全面电动化城市试点，加快充换电设施建设，推动实现信息共享、统一结算。</div><div><br></div><div>针对新能源汽车市场地方保护问题，郭守刚表示，2022年3月印发的《关于建设全国统一大市场的意见》明确提出“加快清理废除妨碍统一市场和公平竞争的各种规定和做法”，《反垄断法》规定不得对外地商品设定歧视性措施，《若干措施》也提出不得设定本地车型备案目录和不合理车辆参数指标。“前期我们已经联合相关部门针对地方保护问题开展了专项督查，后续将加强对地方政策措施的监督核查，推动建设高效规范、公平竞争、统一开放的全国大市场，为我国新能源汽车规模化发展营造良好环境。”</div><div><br></div><div>据悉，近年来，我国新能源汽车市场规模快速扩大，带动我国新能源汽车产品市场竞争力的快速提升。2021年，新能源汽车的消费者满意度已经追平传统燃油汽车。在全球十大畅销新能源汽车车型中有六款是中国品牌车型。今年1-5月，自主品牌新能源乘用车消费占比也已经超过80%。</div>', 0, 3, 1657356610, 1657356715, 1657358359);
COMMIT;

-- ----------------------------
-- Table structure for app_news_category
-- ----------------------------
DROP TABLE IF EXISTS `app_news_category`;
CREATE TABLE `app_news_category` (
  `category_id` int NOT NULL AUTO_INCREMENT COMMENT '分类ID',
  `category_name` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分类名称',
  `sort` tinyint(1) NOT NULL DEFAULT '0' COMMENT '排序，数字越大权重越高',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用，2停用，3删除',
  `created_at` int NOT NULL DEFAULT '0' COMMENT '创建时间',
  `updated_at` int NOT NULL DEFAULT '0' COMMENT '更新时间',
  PRIMARY KEY (`category_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='新闻分类表';

-- ----------------------------
-- Records of app_news_category
-- ----------------------------
BEGIN;
INSERT INTO `app_news_category` (`category_id`, `category_name`, `sort`, `status`, `created_at`, `updated_at`) VALUES (1, '企业新闻', 0, 1, 1650423590, 1656574464);
INSERT INTO `app_news_category` (`category_id`, `category_name`, `sort`, `status`, `created_at`, `updated_at`) VALUES (2, '行业资讯', 0, 1, 1650423601, 1656574479);
INSERT INTO `app_news_category` (`category_id`, `category_name`, `sort`, `status`, `created_at`, `updated_at`) VALUES (3, '常见问题', 0, 1, 1656574490, 0);
COMMIT;

-- ----------------------------
-- Table structure for app_platform
-- ----------------------------
DROP TABLE IF EXISTS `app_platform`;
CREATE TABLE `app_platform` (
  `platform_id` int NOT NULL AUTO_INCREMENT COMMENT '平台ID',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '公司名称',
  `logo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '公司logo',
  `title` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'SEO标题',
  `keywords` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'SEO关键字',
  `description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'SEO描述',
  `main_product` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '主营产品',
  `about` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '首页_关于我们',
  `about_img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '首页_关于我们图片',
  `about_video` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '首页_关于我们视频',
  `contact_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '销售经理',
  `telephone` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '联系座机',
  `phone` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '联系电话',
  `phone2` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '联系电话2',
  `qq` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'QQ',
  `qq2` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'QQ2',
  `email` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '邮箱',
  `address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '公司地址',
  `address2` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '公司地址2',
  `address_longitude` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '公司地址经度',
  `address_latitude` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '公司地址维度',
  `address2_longitude` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '公司地址2经度',
  `address2_latitude` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '公司地址2维度',
  `wechat` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信',
  `wechat_img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信二维码',
  `copyright` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '版权',
  `introduce` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '公司简介',
  `video` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '厂家视频',
  `video_poster` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '厂家视频封面',
  PRIMARY KEY (`platform_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='平台基础配置表';

-- ----------------------------
-- Records of app_platform
-- ----------------------------
BEGIN;
INSERT INTO `app_platform` (`platform_id`, `name`, `logo`, `title`, `keywords`, `description`, `main_product`, `about`, `about_img`, `about_video`, `contact_name`, `telephone`, `phone`, `phone2`, `qq`, `qq2`, `email`, `address`, `address2`, `address_longitude`, `address_latitude`, `address2_longitude`, `address2_latitude`, `wechat`, `wechat_img`, `copyright`, `introduce`, `video`, `video_poster`) VALUES (1, '深圳市云轻电子有限公司', '/upload/logo/20220719/1658224333_logo.png', '深圳市云轻电子有限公司', '深圳市云轻电子有限公司,电子,芯片,电容,钽电容,贴片电容', '深圳市云轻电子有限公司', '钽电容、铝电解电容', '<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;深圳市云轻电子限公司位于深圳华强北，是AVX钽电容优秀供应商之一，公司只做原装正品物料，优势渠道，优势价格，欢迎客户询价咨询！</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; ● 主营：AVX钽电容现货，TAJ系列，TPS系列产品。主要代理AVX，KEMET钽电容，只做原装正品，料号齐全，欢迎采购！ </p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; ● 公司主营产品：AVX钽电容&nbsp; KEMET钽电容&nbsp; &nbsp;NICHICON钽电容&nbsp; &nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; ●&nbsp;公司成立以来，积极拓展渠道关系，保证了产品原装可追溯，给客户提供原厂售后保障。为了满足客户需求，公司深圳仓库常备现货库存，现货库存保证当天发货。</p><p>云轻电子秉承着以客户为中心，诚信至上的经营原则竭诚为广大客户服务。</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; ● 主要特点：钽电容的性能优异，是电容器中体积小而又能达到较大电容量的产品，在电源滤波、交流旁路等用途上少有竞争对手。钽电容以独特的工艺使得其工作温度范围宽， 温度范围在零下25度到125度，另外稳定性强、精准度高、体积小的优良性能，并且这种电容通过<u>氧化</u>膜介质加固和恢复其绝缘能力，具有独特的自愈功</p><p>&nbsp;能，使其不致以遭到连结的累积性损坏。</p>', 'https://www.yunqingelec.com/upload/editorFile/20220725/1658733841_微信图片_20220725145735.png', 'https://www.yunqingelec.com/upload/editorFile/20220725/1658733837_0eb033287debccc6d97227f16a13ac58.mp4', '廖先生', '0755-23209605', '19128301067', '18923848018', '3001156857', '609374129', '609374129@qq.com', '广东省深圳市华强电子世界1号店3楼13C070', '广东省深圳市电子科技大厦C座38楼3889', '114.092926', '22.547283', '121.484331', '31.244875', '19128301067', '/upload/logo/20220709/1657355913_二维码.png', 'Copyright@2022   All Rights Reserved. 粤ICP备2022046179号-1', '<h3><p style=\"font-size: 14px; font-weight: 400;\">深圳市云轻电子限公司位于深圳华强北，是AVX钽电容优秀供应商之一，公司只做原装正品物料，优势渠道，优势价格，欢迎客户询价咨询！</p><p style=\"font-size: 14px; font-weight: 400;\">● 主营：AVX钽电容现货，TAJ系列，TPS系列产品。主要代理AVX，KEMET钽电容，只做原装正品，料号齐全，欢迎采购！</p><p style=\"font-size: 14px; font-weight: 400;\">● 公司主营产品：AVX钽电容&nbsp; KEMET钽电容&nbsp; &nbsp;NICHICON钽电容&nbsp; &nbsp;</p><p style=\"\">公司成立以来，积极拓展渠道关系，保证了产品原装可追溯，给客户提供原厂售后保障。为了满足客户需求，公司深圳仓库常备现货库存，现货库存保证当天发货。</p><p style=\"\">云轻电子秉承着以客户为中心，诚信至上的经营原则竭诚为广大客户服务。</p><p style=\"font-size: 14px; font-weight: 400;\">● 主要特点：钽电容的性能优异，是电容器中体积小而又能达到较大电容量的产品，在电源滤波、交流旁路等用途上少有竞争对手。钽电容以独特的工艺使得其工作温度范围宽，温度范围在零下25度到125度，另外稳定性强、精准度高、体积小的优良性能，并且这种电容通过<u>氧化</u>膜介质加固和恢复其绝缘能力，具有独特的自愈功能，使其不致以遭到连结的累积性损坏。</p></h3><p style=\"text-align: left;\"><img src=\"https://wenbo.100-union.com/upload/editorImg/20220708/1657275728_about.png\" alt=\"\" style=\"width:750px;height:450px;\"></p>', 'https://www.yunqingelec.com/upload/editorFile/20220722/1658479704_1132c390f1f631e7620fa2839d733df7.mp4', 'https://www.yunqingelec.com/upload/editorFile/20220722/1658479710_微信图片_20220722164632.png');
COMMIT;

-- ----------------------------
-- Table structure for app_product
-- ----------------------------
DROP TABLE IF EXISTS `app_product`;
CREATE TABLE `app_product` (
  `product_id` int NOT NULL AUTO_INCREMENT COMMENT '产品ID',
  `category_id` int NOT NULL DEFAULT '0' COMMENT '栏目ID',
  `product_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '产品名称',
  `img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '产品图片',
  `desc` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '产品描述',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '产品说明',
  `sort` tinyint(1) NOT NULL DEFAULT '0' COMMENT '排序，数字越大权重越高',
  `recommend` tinyint(1) NOT NULL DEFAULT '1' COMMENT '推荐：1不推荐，2推荐',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用，2停用，3删除',
  `created_at` int NOT NULL DEFAULT '0' COMMENT '创建时间',
  `updated_at` int NOT NULL DEFAULT '0' COMMENT '更新时间',
  PRIMARY KEY (`product_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=50 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='产品表';

-- ----------------------------
-- Records of app_product
-- ----------------------------
BEGIN;
