-- ----------------------------
-- Table structure for app_product_category
-- ----------------------------
DROP TABLE IF EXISTS `app_product_category`;
CREATE TABLE `app_product_category` (
  `category_id` int NOT NULL AUTO_INCREMENT COMMENT '栏目ID',
  `parent_id` int NOT NULL DEFAULT '0' COMMENT '父级栏目ID',
  `category_name` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '栏目名称',
  `img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '栏目图片',
  `sort` tinyint(1) NOT NULL DEFAULT '0' COMMENT '排序，数字越大权重越高',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用，2停用，3删除',
  `created_at` int NOT NULL DEFAULT '0' COMMENT '创建时间',
  `updated_at` int NOT NULL DEFAULT '0' COMMENT '更新时间',
  PRIMARY KEY (`category_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='产品栏目表';

