-- ----------------------------
-- Table structure for app_qualification
-- ----------------------------
DROP TABLE IF EXISTS `app_qualification`;
CREATE TABLE `app_qualification` (
  `qualification_id` int NOT NULL AUTO_INCREMENT COMMENT '资质ID',
  `category_id` int NOT NULL DEFAULT '1' COMMENT '资质栏目ID',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '名称',
  `img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '图片',
  `file_src` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '文件',
  `sort` tinyint(1) NOT NULL DEFAULT '0' COMMENT '排序，数字越大权重越高',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用，2停用，3删除',
  `created_at` int NOT NULL DEFAULT '0' COMMENT '创建时间',
  `updated_at` int NOT NULL DEFAULT '0' COMMENT '更新时间',
  PRIMARY KEY (`qualification_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='资质表';

